async function n(){const t=window.APP_CONFIG?.baseUrl||"/";try{const e=await(await fetch(`${t}api/sports`)).json();return e.success?e.data.map(r=>({id:r.sport_id,name:r.sport_name})):[]}catch(s){return console.error("Fetch Sports Error:",s),[]}}async function c(t=null){const s=window.APP_CONFIG?.baseUrl||"/",e=t?`${s}api/leagues?sport_id=${t}`:`${s}api/leagues`;try{const o=await(await fetch(e)).json();return o.success?o.data.map(a=>({id:a.league_id,name:a.league,sportId:a.sport_id})):[]}catch(r){return console.error("Fetch Leagues Error:",r),[]}}async function i(){const t=window.APP_CONFIG?.baseUrl||"/";try{const e=await(await fetch(`${t}api/sports?status=all`)).json();return e.success?e.data.map(r=>({id:r.sport_id,name:r.sport_name,isActive:r.status_id===1})):[]}catch(s){return console.error("Fetch All Sports Error:",s),[]}}async function u(t=null){const s=window.APP_CONFIG?.baseUrl||"/",e=t?`${s}api/leagues?status=all&sport_id=${t}`:`${s}api/leagues?status=all`;try{const o=await(await fetch(e)).json();return o.success?o.data.map(a=>({id:a.league_id,name:a.league,sportId:a.sport_id,isActive:a.status_id===1})):[]}catch(r){return console.error("Fetch All Leagues Error:",r),[]}}async function l(t=null){const s=window.APP_CONFIG?.baseUrl||"/",e=t?`${s}api/divisions?league_id=${t}`:`${s}api/divisions`;try{const o=await(await fetch(e)).json();return o.success?o.data.map(a=>({id:a.division_id,name:a.division,price:parseFloat(a.price),leagueId:a.league_id})):[]}catch(r){return console.error("Fetch Divisions Error:",r),[]}}async function d(){const t=window.APP_CONFIG?.baseUrl||"/";try{const e=await(await fetch(`${t}api/divisions?status=all`)).json();return e.success?e.data:[]}catch(s){return console.error("Fetch All Divisions Error:",s),[]}}async function p(){const t=window.APP_CONFIG?.baseUrl||"/";try{const e=await(await fetch(`${t}api/sources`)).json();return e.success?e.data.map(r=>({id:r.entry_id,name:r.hear_about_us})):[]}catch(s){return console.error("Fetch Sources Error:",s),[]}}export{u as a,n as b,p as c,c as d,l as e,i as f,d as g};
